---@class Puzzle_3_RubikEntity
local Puzzle_3_RubikEntity = Class('Puzzle_3_RubikEntity')

-- !!! 此处禁止循环引用 Puzzle_3 ...

--- funtoy:
local KTool = CS.Engine.Lib.KTool
local IDComp = CS.Game.Native.Common.ID

---:
local Object = CS.UnityEngine.Object
local Transform = CS.UnityEngine.Transform
local Vector3 = CS.UnityEngine.Vector3
local Vector2Int = CS.UnityEngine.Vector2Int
local MeshRenderer = CS.UnityEngine.MeshRenderer
local SpriteRenderer = CS.UnityEngine.SpriteRenderer
local Color = CS.UnityEngine.Color
local Mathf = CS.UnityEngine.Mathf
local Time = CS.UnityEngine.Time


-- ==================================================


local upMaskColor = 1.0   -- up 面片 全亮
local downMaskColor = 0.9 -- down 面片要适当变暗一点点


-- ==================================================
   

---@param idComp Game.Native.Common.ID
function Puzzle_3_RubikEntity:__init( idComp )
    assert( not isNull(idComp) )
    
    self.srcPos = nil
    self.tgtPos = nil -- Vector3, 一次移动的起点和终点;
    self.t = 0.0
    self.id = idComp.id
    self.gameObj = idComp.gameObject
    self.transform = self.gameObj.transform


    self.renderers = {} -- List<SpriteRenderer> table, 运行时自己查找 子元素填入体内...
    local srs = self.gameObj:GetComponentsInChildren(typeof(SpriteRenderer),true) -- 包含自己 Array 
    for i=0, srs.Length-1 do 
        local sr = srs[i]
        if sr.name == "up" then
            self.renderers.up = sr
        elseif sr.name == "down" then
            self.renderers.down = sr
        end
    end


end


function Puzzle_3_RubikEntity:__delete()
    self.ClassID = nil
end




-- =============================================================== Self -> ================================================================== -- 



---@return string
function Puzzle_3_RubikEntity.GetClassID()
    return  "RubikEntity"
end



-- 可被反复调用, (1)从配表中默认初始化; (2)从游戏存档中初始化
---@param puzzle_ Puzzle_3
---@param initIdx_ UnityEngine.Vector2Int
---@param initAlpha_ number
---@return Puzzle_3_RubikEntity
function Puzzle_3_RubikEntity:Init( puzzle_, initIdx_, initAlpha_ )
    
    self.puzzle = puzzle_ -- Puzzle_3

    -- 为规避循环引用 而暂时存储的 函数指针: 
    self.CalcRubicEntPos = self.puzzle.CalcRubicEntPos

    self.isOnDestroying = false -- boolean, 
    self.lastIdx = initIdx_ -- Vector2Int
    self.tgtIdx = initIdx_ --  Vector2Int
    self.currentAlpha = initAlpha_ -- float
    self.srcAlpha = initAlpha_     -- float
    self.tgtAlpha = initAlpha_     -- float
    
    self:SetUpDownAlpha( initAlpha_ )

    self:SetOrderInLayers()

    self.transform.position = self.CalcRubicEntPos(self.puzzle, initIdx_ ) -- 函数指针
    self.srcPos = self.transform.position
    self.tgtPos = self.transform.position
    return self
end




function Puzzle_3_RubikEntity:SetUpDownAlpha( tgtAlpha_ )
    if self.renderers.up ~= nil then 
        self.renderers.up.color = Color( upMaskColor, upMaskColor, upMaskColor, tgtAlpha_)
    end
    if self.renderers.down ~= nil then 
        self.renderers.down.color = Color( downMaskColor, downMaskColor, downMaskColor, tgtAlpha_)
    end
end 






---@param idxOffset_ UnityEngine.Vector2Int
---@param tgtAlpha_ number
---@return void
function Puzzle_3_RubikEntity:PrepareForNewMove( idxOffset_, tgtAlpha_ )

    assert( self.lastIdx == self.tgtIdx, "lastIdx = " .. self.lastIdx:ToString() .. "; tgtIdx = " .. self.tgtIdx:ToString() )
    self.tgtIdx = self.lastIdx + idxOffset_
    self.srcAlpha = self.tgtAlpha
    self.tgtAlpha = tgtAlpha_
    self.srcPos = self.tgtPos
    self.tgtPos = self.CalcRubicEntPos(self.puzzle, self.tgtIdx) -- 函数指针
    self.t = 0.0
end



-- ret: 移动到终点时, 返回 true;
---@return boolean
function Puzzle_3_RubikEntity:MoveOneFrame()

    local tSpeed = 1.8
    self.t = self.t + Time.deltaTime * tSpeed
    local smooth_t = Mathf.SmoothStep(0, 1, Mathf.Clamp01(self.t) )

    self.transform.position = Vector3.Lerp( self.srcPos,   self.tgtPos,   smooth_t )
    self.currentAlpha       = Mathf.Lerp(   self.srcAlpha, self.tgtAlpha, smooth_t )

    self:SetUpDownAlpha( self.currentAlpha )

    return self.t > 1.0
end



function Puzzle_3_RubikEntity:EndTheMove()
    self.lastIdx = self.tgtIdx;
    -- todo: 如果自己进入销毁阶段, 那么要在此处销毁自己...
    if self.isOnDestroying  then
        Object.Destroy( self.gameObj );
    end
end 




function Puzzle_3_RubikEntity:OnDisable()
end




function Puzzle_3_RubikEntity:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    print("   ~~~~~~~ Puzzle_3_RubikEntity:OnDestroy() ~~~~~~~")
end




function Puzzle_3_RubikEntity:SetOrderInLayers()
    if self.renderers.down ~= nil then 
        self.renderers.down.sortingOrder = self.puzzle:Vec2_2_OrderInLayer( self.tgtIdx, -20 )
    end 
    if self.renderers.up ~= nil then 
        self.renderers.up.sortingOrder = self.puzzle:Vec2_2_OrderInLayer( self.tgtIdx, -10 )
    end 
end


function Puzzle_3_RubikEntity:DebugInfo()
    local s = "{ id: " .. tostring(self.id) .. ", name: " .. self.gameObj.name .. " }"
    return s
end


return Puzzle_3_RubikEntity
